static unsigned route237(float sx,float sy,const WorldGate*goal){unsigned n=gw*gh,start=(unsigned)(sy/8)*gw+(unsigned)(sx/8),*q=malloc(n*4);unsigned char*seen=calloc(n,1);assert(q&&seen&&start<n);q[0]=start;seen[start]=1;unsigned head=0,tail=1,found=0;while(head<tail){unsigned node=q[head++];float x=node==start?sx:(node%gw)*8+4,y=node==start?sy:(node/gw)*8+4;if(fabsf(x-goal->x)<=goal->rx&&fabsf(y-goal->y)<=goal->ry){found=1;break;}int dx[]={-1,1,0,0},dy[]={0,0,-1,1};for(unsigned k=0;k<4;k++){int xx=(int)(node%gw)+dx[k],yy=(int)(node/gw)+dy[k];if(xx<1||yy<1||xx>=(int)gw-1||yy>=(int)gh-1)continue;unsigned next=yy*gw+xx;if(seen[next]||!world_can_move(NULL,x,y,xx*8+4,yy*8+4))continue;seen[next]=1;q[tail++]=next;}}free(q);free(seen);return found;}
